import org.junit.jupiter.api.Test;

class BlankNodeSolutionOccurrenceTest {
	@Test
	void separateExtensionStagesUseDistinctLabelsAndReusedInputOccurrencesRemainFresh() {
		var context = new QueryEvaluationContext.Minimal(null);
		var vf = SimpleValueFactory.getInstance();
		BindingSet reusableInput = new MapBindingSet();
		var input = new CloseableIteratorIteration<>(List.of(reusableInput, reusableInput).iterator());
		var firstBind = new ExtensionIterator(input,
				target -> {
					Value first = context.getOrCreateBNode("label", target, vf);
					Value repeated = context.getOrCreateBNode("label", target, vf);
					assertEquals(first, repeated, "calls in one extension stage share the label");
					target.setBinding("first", first);
				}, context);
		try (var secondBind = new ExtensionIterator(firstBind,
				target -> target.setBinding("second", context.getOrCreateBNode("label", target, vf)), context)) {
			BindingSet first = secondBind.next();
			BindingSet second = secondBind.next();
			assertNotEquals(first.getValue("first"), first.getValue("second"),
					"a later extension stage starts a fresh BNODE label scope");
			assertNotEquals(second.getValue("first"), second.getValue("second"),
					"each later extension stage starts a fresh BNODE label scope");
			assertNotEquals(first.getValue("first"), second.getValue("first"),
					"two input occurrences remain distinct even if their source BindingSet object is identical");
			assertFalse(secondBind.hasNext());
		}
	}

	@Test
	void parsedBindStagesUseDistinctLabels() throws Exception {
		ParsedTupleQuery parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT ?first ?second WHERE { VALUES ?x { 1 } "
						+ "BIND(BNODE(\"label\") AS ?first) BIND(BNODE(\"label\") AS ?second) }",
				null);
		var strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		try (var results = strategy.evaluate(parsed.getTupleExpr(), EmptyBindingSet.getInstance())) {
			BindingSet row = results.next();
			assertNotEquals(row.getValue("first"), row.getValue("second"),
					"separate parsed BIND stages create distinct BNODE label scopes");
			assertFalse(results.hasNext());
		}
	}

	@Test
	void repeatedLabelCallsWithinExpressionShareIdentity() {
		var context = new QueryEvaluationContext.Minimal(null);
		var vf = SimpleValueFactory.getInstance();
		BindingSet input = new MapBindingSet();
		try (var extension = new ExtensionIterator(new CloseableIteratorIteration<>(List.of(input).iterator()),
				target -> {
					Value first = context.getOrCreateBNode("label", target, vf);
					Value second = context.getOrCreateBNode("label", target, vf);
					assertEquals(first, second);
					target.setBinding("node", first);
				}, context)) {
			extension.next();
			assertFalse(extension.hasNext());
		}
	}
}
